import{_ as t,l as h,o as e,c as l,v as r,p as n,x as i,d as s,i as f,S as c}from"./chunks/framework.InCnrqk-.js";const F=JSON.parse('{"title":"Kirchhoff 对严格电磁","description":"","frontmatter":{"title":"Kirchhoff 对严格电磁","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/kirchhoff-vs-emf.md","filePath":"litho/kirchhoff-vs-emf.md","lastUpdated":1789023840000}'),p={name:"litho/kirchhoff-vs-emf.md"};function E(d,a,m,B,D,_){const o=h("Mermaid");return e(),l("div",null,[a[1]||(a[1]=r('<h1 id="kirchhoff-对严格电磁" tabindex="-1">Kirchhoff 对严格电磁 <a class="header-anchor" href="#kirchhoff-对严格电磁" aria-label="Permalink to &quot;Kirchhoff 对严格电磁&quot;">​</a></h1><div class="epigraph"><p>薄屏把开口乘上一个 $t(x,y)$ 就做衍射；吸收体一厚，开口是波导，级振幅必须解麦克斯韦，而不是再乘一层经验透过率。</p><footer>—— 据 Wong 对投影光刻成像与厚掩模衍射的论述，以及 Erdmann 等对严格电磁（EMF）掩模模拟的表述</footer></div><p><a href="/litho/mask-3d-effect">上一课</a>已经列出 M3D 的晶圆后果：HV 偏置、焦漂、左右不对称，并声明 OPC 要含厚掩模衍射级。缺口是计算接口：何时 Kirchhoff 薄屏还够用，何时必须 RCWA、FDTD 或等价严格电磁。几何阴影的斜入射图留给<a href="/litho/mask-shadowing">下一课</a>，本课不把 6° 再讲成一套新效应。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>上一课的对照物是薄屏 \\(t(x,y)\\)。量产 OPC 仍大量从 Kirchhoff（或薄屏加标量角谱）起步，再决定要不要换电磁级库。若处处 FDTD，全芯片跑不起；若永远薄屏，SRAF 与离轴级振幅会系统错。需要一条切换判据，而不是把「有厚度」再描述一遍。</p><p>缺口因此是两种求解器的误差账：Kirchhoff 何时失败。失败指衍射级的复振幅（含偏振）相对严格解不可忽略，从而 EPE 与最佳焦距漂出预算——不是「掩模看起来立体」。</p><h3 id="薄屏忽略的边值" tabindex="-1">薄屏忽略的边值 <a class="header-anchor" href="#薄屏忽略的边值" aria-label="Permalink to &quot;薄屏忽略的边值&quot;">​</a></h3><p>Kirchhoff 假定开口平面上的场等于入射场乘规定透过率，开口外为零，忽略边缘散射、波导模式、侧壁角与材料色散。Wong 把投影成像建在这个物体频谱上；Erdmann 等用严格麦克斯韦证明，193 nm 吸收体厚度与波长同量级时，0 级与 ±1 级的相位差已经够把焦点和 HV 偏置做进空中像。</p><p><span class="marginnote">「严格」指掩模近场满足电磁边值，不是晶圆侧也改用 FDTD。晶圆侧仍是矢量成像 + 薄膜栈；贵的是物体频谱那一截。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>实践分层：松节距、近正入射、吸收体相对特征很薄 → Kirchhoff 或薄屏加测量透过率。特征进入波长量级、离轴极大、SRAF 宽度接近膜厚 → 对代表 clips 跑 RCWA / 时域有限差分 / 波导模态，把级振幅制成 M3D 库，全芯片用查找表或代理模型。校准用不同方位、不同密度的线和孔，看薄屏 OPC 残差是否呈系统 HV 与焦漂。</p><p>不要用「加一个全局相位」冒充 EMF：波导相位随开口宽度变，不是常数。att-PSM 的标称 6%+\\(180^\\circ\\) 是膜系目标，有效级振幅以电磁为准。</p><h3 id="与矢量成像的分工" tabindex="-1">与矢量成像的分工 <a class="header-anchor" href="#与矢量成像的分工" aria-label="Permalink to &quot;与矢量成像的分工&quot;">​</a></h3><p><a href="/litho/vector-imaging">矢量成像</a>处理投影侧大夹角的 s/p。本课处理物体侧：掩模把入射琼斯变成衍射级琼斯。两段都忽略，标量 \\(k_1\\) 会双重乐观。计算上可以先薄屏矢量，再换成厚掩模矢量；顺序不能把 EMF 理解成「已经包含浸没」。</p>',14)),(e(),n(c,null,{default:i(()=>[f(o,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20KIR%5B%22Kirchhoff%20%E8%96%84%E5%B1%8F%20t(x%2Cy)%22%5D%20--%3E%20OK%5B%22%E6%9D%BE%E8%8A%82%E8%B7%9D%20%2F%20%E8%BF%91%E6%AD%A3%E5%85%A5%E5%B0%84%22%5D%0A%20%20EMF%5B%22RCWA%20%2F%20FDTD%20%E7%BA%A7%E6%8C%AF%E5%B9%85%22%5D%20--%3E%20FAIL%5B%22%E5%8E%9A%E5%90%B8%E6%94%B6%E4%BD%93%20%E7%A6%BB%E8%BD%B4%20SRAF%22%5D%0A%20%20KIR%20--%3E%20ERR%5B%22%E7%BA%A7%E7%9B%B8%E4%BD%8D%E7%B3%BB%E7%BB%9F%E5%81%8F%E5%B7%AE%22%5D%0A%20%20EMF%20--%3E%20LIB%5B%22M3D%20%E5%BA%93%E8%BF%9B%20OPC%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>误差首先出现在级的相对相位：薄屏按 \\(\\Delta n\\cdot t\\) 给一块均匀相移，严格解按开口宽度选波导常数。于是干涉条件随 CD 变，最佳焦距变成图形相关。其次是级的振幅比：边缘散射让「有效开口」不等于顶视多边形，MEF 与 SRAF 透过都偏离面积比。偏振：线栅掩模对 s/p 透过不同，薄屏若只用标量 \\(t\\)，等于丢掉掩模偏振器。</p><p>全芯片仍不能处处严格：域分解、边查表、机器学习代理都是在逼近这份级库。校正环必须调用同一份库，否则离轴方向的放置误差系统性偏。</p><p><span class="marginnote">ILT 曲边在 Kirchhoff 下好看、在 EMF 下可能违 MRC 或阴影异常。曲掩模签字必须以严格级振幅为准，不能用薄屏 ILT 直接写版。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不展开阴影的狭缝扫描几何——那是斜入射投影的下一课，尽管求解器仍是 EMF。也不把掩模台倾斜、pellicle 皱纹叫做 Kirchhoff 失效。低 \\(k_1\\) 默认含 M3D；教学零阶仍允许薄屏，但后课写 OPC/SMO 时薄屏只作对照。</p><p>不要给 Wong 或 Erdmann 编造不存在的文献编号。出处是投影光刻成像专论与严格掩模衍射的公开文献传统。本课不提供「193 nm 必须 EMF 的纳米阈值」当宇宙常数：判据随膜系、照明角与预算变。</p><p>计算预算上，代表 clips 的严格解可以很贵，但仍远小于全芯片 FDTD。工程失败模式是：库的几何覆盖不到真实侧壁角或膜厚批次，OPC 以为自己在用 EMF，实际在用过期表。</p><p><span class="marginnote">EUV 多层膜加吸收体几乎总是 EMF 区；DUV 仍可能对松层用薄屏。切换看误差预算，不看节点商品名。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Kirchhoff 薄屏是零阶物体频谱；厚掩模要解麦克斯韦得级振幅。</li><li>失败信号是级相位/振幅系统偏差，表现为 HV、焦漂、SRAF 透过失常。</li><li>全芯片用 EMF 库 + 紧凑模型，不是每处 FDTD。</li><li>阴影几何下一课；本课钉求解器切换。</li><li>出处：Wong 投影光刻成像与厚掩模衍射；Erdmann 等严格 EMF 掩模模拟。</li></ul>',11))])}const u=t(p,[["render",E]]);export{F as __pageData,u as default};
